-- Payables-owned append-only evidence and parent-key protection.
CREATE TRIGGER fb_payables_billrevision_update BEFORE UPDATE ON payables_billrevision BEGIN SELECT RAISE(ABORT,'bill_history_immutable: Bill revisions are immutable'); END;
CREATE TRIGGER fb_payables_billrevision_delete BEFORE DELETE ON payables_billrevision BEGIN SELECT RAISE(ABORT,'bill_history_immutable: Bill revisions are immutable'); END;
CREATE TRIGGER fb_payables_billline_update BEFORE UPDATE ON payables_billline BEGIN SELECT RAISE(ABORT,'bill_history_immutable: Bill lines are immutable'); END;
CREATE TRIGGER fb_payables_billline_delete BEFORE DELETE ON payables_billline BEGIN SELECT RAISE(ABORT,'bill_history_immutable: Bill lines are immutable'); END;
CREATE TRIGGER fb_payables_billpayment_update BEFORE UPDATE ON payables_billpayment BEGIN SELECT RAISE(ABORT,'payment_immutable: Payment history is immutable'); END;
CREATE TRIGGER fb_payables_billpayment_delete BEFORE DELETE ON payables_billpayment BEGIN SELECT RAISE(ABORT,'payment_immutable: Payment history is immutable'); END;
CREATE TRIGGER fb_payables_paymentallocation_update BEFORE UPDATE ON payables_paymentallocation BEGIN SELECT RAISE(ABORT,'payment_immutable: Allocation history is immutable'); END;
CREATE TRIGGER fb_payables_paymentallocation_delete BEFORE DELETE ON payables_paymentallocation BEGIN SELECT RAISE(ABORT,'payment_immutable: Allocation history is immutable'); END;
CREATE TRIGGER fb_payables_paymentreversal_update BEFORE UPDATE ON payables_paymentreversal BEGIN SELECT RAISE(ABORT,'payment_immutable: Reversal history is immutable'); END;
CREATE TRIGGER fb_payables_paymentreversal_delete BEFORE DELETE ON payables_paymentreversal BEGIN SELECT RAISE(ABORT,'payment_immutable: Reversal history is immutable'); END;
CREATE TRIGGER fb_payables_directory_vendor_kept BEFORE DELETE ON directory_vendor WHEN EXISTS(SELECT 1 FROM payables_billrevision WHERE vendor_id=OLD.id) OR EXISTS(SELECT 1 FROM payables_billpayment WHERE vendor_id=OLD.id) BEGIN SELECT RAISE(ABORT,'payables_parent: Referenced parents cannot be deleted or replaced'); END;
CREATE TRIGGER fb_payables_directory_vendor_replace BEFORE INSERT ON directory_vendor WHEN EXISTS(SELECT 1 FROM directory_vendor OLD WHERE (id=NEW.id) AND (EXISTS(SELECT 1 FROM payables_billrevision WHERE vendor_id=OLD.id) OR EXISTS(SELECT 1 FROM payables_billpayment WHERE vendor_id=OLD.id))) BEGIN SELECT RAISE(ABORT,'payables_parent: Referenced parents cannot be deleted or replaced'); END;
CREATE TRIGGER fb_payables_directory_vendor_scope BEFORE UPDATE ON directory_vendor WHEN (NEW.id<>OLD.id OR NEW.company_id<>OLD.company_id) AND (EXISTS(SELECT 1 FROM payables_billrevision WHERE vendor_id=OLD.id) OR EXISTS(SELECT 1 FROM payables_billpayment WHERE vendor_id=OLD.id)) BEGIN SELECT RAISE(ABORT,'payables_parent_scope: Historical parents cannot move company'); END;
CREATE TRIGGER fb_payables_directory_item_kept BEFORE DELETE ON directory_item WHEN EXISTS(SELECT 1 FROM payables_billline WHERE item_id=OLD.id) BEGIN SELECT RAISE(ABORT,'payables_parent: Referenced parents cannot be deleted or replaced'); END;
CREATE TRIGGER fb_payables_directory_item_replace BEFORE INSERT ON directory_item WHEN EXISTS(SELECT 1 FROM directory_item OLD WHERE (id=NEW.id OR (company_id=NEW.company_id AND fb_lower(code)=fb_lower(NEW.code))) AND (EXISTS(SELECT 1 FROM payables_billline WHERE item_id=OLD.id))) BEGIN SELECT RAISE(ABORT,'payables_parent: Referenced parents cannot be deleted or replaced'); END;
CREATE TRIGGER fb_payables_directory_item_scope BEFORE UPDATE ON directory_item WHEN (NEW.id<>OLD.id OR NEW.company_id<>OLD.company_id) AND (EXISTS(SELECT 1 FROM payables_billline WHERE item_id=OLD.id)) BEGIN SELECT RAISE(ABORT,'payables_parent_scope: Historical parents cannot move company'); END;
CREATE TRIGGER fb_payables_ledger_account_kept BEFORE DELETE ON ledger_account WHEN EXISTS(SELECT 1 FROM payables_billline WHERE OLD.id IN(income_account_id,expense_account_id)) OR EXISTS(SELECT 1 FROM payables_billpayment WHERE bank_id=OLD.id) OR EXISTS(SELECT 1 FROM payables_paymentallocation WHERE payables_id=OLD.id) BEGIN SELECT RAISE(ABORT,'payables_parent: Referenced parents cannot be deleted or replaced'); END;
CREATE TRIGGER fb_payables_ledger_account_replace BEFORE INSERT ON ledger_account WHEN EXISTS(SELECT 1 FROM ledger_account OLD WHERE (id=NEW.id OR (company_id=NEW.company_id AND code=NEW.code)) AND (EXISTS(SELECT 1 FROM payables_billline WHERE OLD.id IN(income_account_id,expense_account_id)) OR EXISTS(SELECT 1 FROM payables_billpayment WHERE bank_id=OLD.id) OR EXISTS(SELECT 1 FROM payables_paymentallocation WHERE payables_id=OLD.id))) BEGIN SELECT RAISE(ABORT,'payables_parent: Referenced parents cannot be deleted or replaced'); END;
CREATE TRIGGER fb_payables_ledger_account_scope BEFORE UPDATE ON ledger_account WHEN (NEW.id<>OLD.id OR NEW.company_id<>OLD.company_id) AND (EXISTS(SELECT 1 FROM payables_billline WHERE OLD.id IN(income_account_id,expense_account_id)) OR EXISTS(SELECT 1 FROM payables_billpayment WHERE bank_id=OLD.id) OR EXISTS(SELECT 1 FROM payables_paymentallocation WHERE payables_id=OLD.id)) BEGIN SELECT RAISE(ABORT,'payables_parent_scope: Historical parents cannot move company'); END;
CREATE TRIGGER fb_payables_documents_documentidentity_kept BEFORE DELETE ON documents_documentidentity WHEN EXISTS(SELECT 1 FROM payables_bill WHERE identity_id=OLD.id) OR EXISTS(SELECT 1 FROM payables_billpayment WHERE identity_id=OLD.id) BEGIN SELECT RAISE(ABORT,'payables_parent: Referenced parents cannot be deleted or replaced'); END;
CREATE TRIGGER fb_payables_documents_documentidentity_replace BEFORE INSERT ON documents_documentidentity WHEN EXISTS(SELECT 1 FROM documents_documentidentity OLD WHERE (id=NEW.id) AND (EXISTS(SELECT 1 FROM payables_bill WHERE identity_id=OLD.id) OR EXISTS(SELECT 1 FROM payables_billpayment WHERE identity_id=OLD.id))) BEGIN SELECT RAISE(ABORT,'payables_parent: Referenced parents cannot be deleted or replaced'); END;
CREATE TRIGGER fb_payables_ledger_journal_kept BEFORE DELETE ON ledger_journal WHEN EXISTS(SELECT 1 FROM payables_billrevision WHERE OLD.id IN(journal_id,reversal_id)) OR EXISTS(SELECT 1 FROM payables_billpayment WHERE journal_id=OLD.id) OR EXISTS(SELECT 1 FROM payables_paymentreversal WHERE journal_id=OLD.id) BEGIN SELECT RAISE(ABORT,'payables_parent: Referenced parents cannot be deleted or replaced'); END;
CREATE TRIGGER fb_payables_ledger_journal_replace BEFORE INSERT ON ledger_journal WHEN EXISTS(SELECT 1 FROM ledger_journal OLD WHERE (id=NEW.id) AND (EXISTS(SELECT 1 FROM payables_billrevision WHERE OLD.id IN(journal_id,reversal_id)) OR EXISTS(SELECT 1 FROM payables_billpayment WHERE journal_id=OLD.id) OR EXISTS(SELECT 1 FROM payables_paymentreversal WHERE journal_id=OLD.id))) BEGIN SELECT RAISE(ABORT,'payables_parent: Referenced parents cannot be deleted or replaced'); END;
CREATE TRIGGER fb_payables_fb_seal_replace BEFORE INSERT ON fb_seal WHEN NEW.kind IN('bill_revision','bill_payment','payables_journal') AND EXISTS(SELECT 1 FROM fb_seal WHERE kind=NEW.kind AND doc_id=NEW.doc_id) BEGIN SELECT RAISE(ABORT,'payables_seal: Payables seals are permanent'); END;
CREATE TRIGGER fb_payables_fb_seal_due_replace BEFORE INSERT ON fb_seal_due WHEN NEW.kind IN('bill_revision','bill_payment','payables_journal') AND EXISTS(SELECT 1 FROM fb_seal_due WHERE kind=NEW.kind AND doc_id=NEW.doc_id) BEGIN SELECT RAISE(ABORT,'payables_seal: Payables seals are permanent'); END;
CREATE TRIGGER fb_bill_update_collision BEFORE UPDATE ON payables_bill WHEN NEW.reference_key<>'' AND NEW.state<>'VOID' AND EXISTS(SELECT 1 FROM payables_bill WHERE id<>OLD.id AND company_id=NEW.company_id AND vendor_id=NEW.vendor_id AND reference_key=NEW.reference_key AND state<>'VOID') BEGIN SELECT RAISE(ABORT,'bill_immutable_ownership: Bills cannot replace existing history'); END;
